from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    sigma = len(alphabet)
    if not banned:
        return pow(sigma, n, MOD)

    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}

    trans: list[list[int]] = [[-1] * sigma]
    is_bad: list[bool] = [False]

    for pattern in banned:
        u = 0
        for ch in pattern:
            c = char_to_idx[ch]
            nxt = trans[u][c]
            if nxt == -1:
                nxt = len(trans)
                trans.append([-1] * sigma)
                is_bad.append(False)
                trans[u][c] = nxt
            u = nxt
        is_bad[u] = True

    num_nodes = len(trans)
    fail = [0] * num_nodes
    queue: deque[int] = deque()

    for c in range(sigma):
        v = trans[0][c]
        if v != -1:
            fail[v] = 0
            queue.append(v)
        else:
            trans[0][c] = 0

    while queue:
        u = queue.popleft()
        if is_bad[fail[u]]:
            is_bad[u] = True
        for c in range(sigma):
            v = trans[u][c]
            if v != -1:
                fail[v] = trans[fail[u]][c]
                if is_bad[u]:
                    is_bad[v] = True
                queue.append(v)
            else:
                trans[u][c] = trans[fail[u]][c]

    valid_id = [-1] * num_nodes
    valid_nodes: list[int] = []
    for u in range(num_nodes):
        if not is_bad[u]:
            valid_id[u] = len(valid_nodes)
            valid_nodes.append(u)

    m = len(valid_nodes)
    mat = [[0] * m for _ in range(m)]
    for i, u in enumerate(valid_nodes):
        row = mat[i]
        for c in range(sigma):
            j = valid_id[trans[u][c]]
            if j != -1:
                row[j] += 1

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            ai = a[i]
            ri = res[i]
            for k in range(m):
                aik = ai[k]
                if aik:
                    bk = b[k]
                    for j in range(m):
                        ri[j] += aik * bk[j]
            for j in range(m):
                ri[j] %= MOD
        return res

    def vec_mat_mul(v: list[int], a: list[list[int]]) -> list[int]:
        res = [0] * m
        for i in range(m):
            vi = v[i]
            if vi:
                ai = a[i]
                for j in range(m):
                    res[j] += vi * ai[j]
        return [x % MOD for x in res]

    vec = [0] * m
    vec[valid_id[0]] = 1

    exp = n
    base = mat
    while exp > 0:
        if exp & 1:
            vec = vec_mat_mul(vec, base)
        exp >>= 1
        if exp > 0:
            base = mat_mul(base, base)

    return sum(vec) % MOD
